# ExtensionKit dlopen entry: OHOS_EXTENSION_GetExtensionModule is the
# dlsym symbol looked up by the extension runtime. The returned loader
# object is used cross-DSO (virtual Create/GetParams under cfi_cross_dso),
# so its vtable, singleton instance and guard must stay exported. The
# mangled wildcard covers all VpnExtensionModuleLoader symbols.
{
  global:
    OHOS_EXTENSION_GetExtensionModule;
    _Z*24VpnExtensionModuleLoader*;
  local:
    *;
};
